VoiceParam_MultiDispatch:
	; --- Dispatcher: 5-way branch on (0x10F2) value (318 bytes total) ---
	ldda8	a, 4337
	ldb l, 0x03
	ldda8	a, 4338
	cp a, l
	jrl z, VoiceParam_Case03
	cp a, 0x08
	jrl z, VoiceParam_Case08
	cp a, 0x0A
	jrl z, VoiceParam_Case0A
	cp a, 0x0B
	jrl z, VoiceParam_Case0B
	; --- Default handler: H=0x4C, L=0x34 ---
	ldda8	a, 4339
	ldb l, 0x34
	ldb h, 0x4C
	call 0xEF6C37
	stda8	4339, a
	stdi8	3571, 4
	call VoiceSlot_ReadParamsWithSaveRestore
	call 0xEFF9EC
	jp VoiceParam_CommonTail
VoiceParam_Case03:
	; --- Case 0x03: H=0x7F, L=0x00 ---
	ldda8	a, 4339
	ldb l, 0x00
	ldb h, 0x7F
	call 0xEF6C37
	stda8	4339, a
	stdi8	3571, 4
	call VoiceSlot_ReadParamsWithSaveRestore
	call 0xEFF8DA
	jp VoiceParam_CommonTail
VoiceParam_Case08:
	; --- Case 0x08: H=0x7F, L=0x00 ---
	ldda8	a, 4339
	ldb l, 0x00
	ldb h, 0x7F
	call 0xEF6C37
	stda8	4339, a
	stdi8	3571, 4
	call VoiceSlot_ReadParamsWithSaveRestore
	call 0xEFF98D
	jp VoiceParam_CommonTail
VoiceParam_Case0A:
	; --- Case 0x0A: H=0xFF, L=0x00 ---
	ldda8	a, 4339
	ldb l, 0x00
	ldb h, 0xFF
	call 0xEF6C37
	stda8	4339, a
	stdi8	3571, 4
	call VoiceParam_BitManipHelper
	call 0xEFFA59
	jp VoiceParam_CommonTail
VoiceParam_Case0B:
	; --- Case 0x0B: H=0x0C, L=0x00 ---
	ldda8	a, 4339
	ldb l, 0x00
	ldb h, 0x0C
	call 0xEF6C37
	stda8	4339, a
	stdi8	3571, 4
	call VoiceSlot_ReadParamsWithSaveRestore
	call 0xEFFB02
VoiceParam_CommonTail:
	; --- Common tail ---
	call Display_UpdateRegion3
	ordi8	58338, 8
	ret
VoiceSlot_ReadParamsWithSaveRestore:
	; --- Helper 1: guard on W, parameter setup + calls (44 bytes) ---
	call 0xEFD286
	cps	w, 0
	jrl z, VoiceParam_SaveRestore_Ret
	xor	a, a
	call VoiceSlot_SaveState
	ldda8	e, 3571
	xor d, d
	call 0xEFC4D1
	call VoiceSlot_ReadCurrentParams
	ldda8	w, 4339
	call 0xEFC49D
	xor	a, a
	call VoiceSlot_RestoreState
VoiceParam_SaveRestore_Ret:
	ret
VoiceParam_BitManipHelper:
	; --- Helper 2: guard on W, bit manipulation + calls (70 bytes) ---
	call 0xEFD286
	cps	w, 0
	jrl z, VoiceParam_BitManip_Ret
	xor	a, a
	call VoiceSlot_SaveState
	call VoiceSlot_ReadCurrentParams
	ldda8	w, 4339
	and w, 0x80
	rlc	w
	and a, 0xFE
	or w, a
	call 0xEFC49D
	ldda8	e, 3571
	xor d, d
	call 0xEFC4D1
	call VoiceSlot_ReadCurrentParams
	ldda8	w, 4339
	and w, 0x7F
	call 0xEFC49D
	xor	a, a
	call VoiceSlot_RestoreState
VoiceParam_BitManip_Ret:
	ret


