VoiceBank_ProcessCommand:
	ld xix, 0xEB5
	call VoiceBank_LoadLerpState
	lda_dpi XBC, 0xF0
	cp a, 0x81
	jrl z, VoiceBank_CallAndReturn
	cp a, 0x82
	jrl z, VoiceBank_CallAndReturn
	cp a, 0x84
	jrl nz, VoiceBank_CallAndLoop

VoiceBank_CallAndReturn:
	call VoiceBank_UpdateLerpState
	jp VoiceBank_Ret

VoiceBank_CallAndLoop:
	call VoiceBank_UpdateLerpState
	call VoiceBank_LoadLerpState
	bit 7, a
	jrl nz, VoiceBank_Ret
	lda_dpi XBC, 0xF0
	jp VoiceBank_CallAndLoop

VoiceBank_Ret:
	ret

VoiceBank_LoadLerpState:
	push xiz
	ldda32 xiz, 4349
	ldfr_lerp XIZ, 0x38
	pop xiz
	push_lerp 0x38
	push xix
	ldda16 xhl, 10431
	call DisplayStr_ComputeTableAddr
	ldda32 xiy, 4349
	ldda16 xix, 10433
	ld_srib3 A, 0x07, 0xF4, 0xF0
	pop xix
	pop_lerp 0x38
	push xiz
	ldto_lerp XIZ, 0x38
	stda32 4349, xiz
	pop xiz
	ret

VoiceBank_UpdateLerpState:
	push xiz
	ldda32 xiz, 4349
	ldfr_lerp XIZ, 0x38
	pop xiz
	push_lerp 0x38
	push xix
	ldda16 xwa, 10433
	cp wa, 0xFF
	jrl nz, VoiceBank_IncrementIndex
	ldda16 xhl, 10431
	call DisplayStr_ComputeTableAddr
	ldda32 xhl, 4349
	ld hl, (xhl + 3)
	stda16 10431, xhl
	lds wa, 5
	jp VoiceBank_StoreIndex

VoiceBank_IncrementIndex:
	inc 1, wa

VoiceBank_StoreIndex:
	stda16 10433, xwa
	pop xix
	pop_lerp 0x38
	push xiz
	ldto_lerp XIZ, 0x38
	stda32 4349, xiz
	pop xiz
	ret

